-- SQL Server 2019+; empty database only. Application manages one encompassing transaction.
CREATE TABLE SchemaMigrations(Version BIGINT PRIMARY KEY, AppliedAt NVARCHAR(40) COLLATE Latin1_General_100_BIN2 NOT NULL);
CREATE TABLE Tenants(Id NVARCHAR(100) COLLATE Latin1_General_100_BIN2 PRIMARY KEY, Name NVARCHAR(MAX) COLLATE Latin1_General_100_BIN2 NOT NULL);
CREATE TABLE Shops(TenantId NVARCHAR(100) COLLATE Latin1_General_100_BIN2 NOT NULL REFERENCES Tenants(Id), Platform NVARCHAR(32) COLLATE Latin1_General_100_BIN2 NOT NULL, Id NVARCHAR(100) COLLATE Latin1_General_100_BIN2 NOT NULL,
    Name NVARCHAR(MAX) COLLATE Latin1_General_100_BIN2 NOT NULL, PRIMARY KEY(TenantId,Platform,Id));
CREATE TABLE Warehouses(TenantId NVARCHAR(100) COLLATE Latin1_General_100_BIN2 NOT NULL REFERENCES Tenants(Id), OwnerId NVARCHAR(100) COLLATE Latin1_General_100_BIN2 NOT NULL, Id NVARCHAR(100) COLLATE Latin1_General_100_BIN2 NOT NULL,
    Name NVARCHAR(MAX) COLLATE Latin1_General_100_BIN2 NOT NULL, PRIMARY KEY(TenantId,OwnerId,Id));
CREATE TABLE Skus(TenantId NVARCHAR(100) COLLATE Latin1_General_100_BIN2 NOT NULL REFERENCES Tenants(Id), Id NVARCHAR(100) COLLATE Latin1_General_100_BIN2 NOT NULL, Code NVARCHAR(100) COLLATE Latin1_General_100_BIN2 NOT NULL,
    Name NVARCHAR(MAX) COLLATE Latin1_General_100_BIN2 NOT NULL, Enabled BIGINT NOT NULL CHECK(Enabled IN(0,1)), ComponentsJson NVARCHAR(MAX) COLLATE Latin1_General_100_BIN2 NOT NULL,
    PRIMARY KEY(TenantId,Id), UNIQUE(TenantId,Code));
CREATE TABLE SkuMappings(TenantId NVARCHAR(100) COLLATE Latin1_General_100_BIN2 NOT NULL, Platform NVARCHAR(32) COLLATE Latin1_General_100_BIN2 NOT NULL, ShopId NVARCHAR(100) COLLATE Latin1_General_100_BIN2 NOT NULL,
    ProductId NVARCHAR(100) COLLATE Latin1_General_100_BIN2 NOT NULL, VariantId NVARCHAR(100) COLLATE Latin1_General_100_BIN2 NOT NULL, SkuId NVARCHAR(100) COLLATE Latin1_General_100_BIN2 NOT NULL, MultiplierUnits BIGINT NOT NULL CHECK(MultiplierUnits>0),
    Version BIGINT NOT NULL CHECK(Version>0), PRIMARY KEY(TenantId,Platform,ShopId,ProductId,VariantId),
    FOREIGN KEY(TenantId,SkuId) REFERENCES Skus(TenantId,Id));
CREATE TABLE Readiness(Platform NVARCHAR(32) COLLATE Latin1_General_100_BIN2 PRIMARY KEY, Revision BIGINT NOT NULL, ItemsJson NVARCHAR(MAX) COLLATE Latin1_General_100_BIN2 NOT NULL);
CREATE TABLE ValidationReports(Id NVARCHAR(100) COLLATE Latin1_General_100_BIN2 PRIMARY KEY, CreatedAt NVARCHAR(40) COLLATE Latin1_General_100_BIN2 NOT NULL, ReportJson NVARCHAR(MAX) COLLATE Latin1_General_100_BIN2 NOT NULL);
CREATE TABLE InventoryBalances(TenantId NVARCHAR(100) COLLATE Latin1_General_100_BIN2 NOT NULL, OwnerId NVARCHAR(100) COLLATE Latin1_General_100_BIN2 NOT NULL, WarehouseId NVARCHAR(100) COLLATE Latin1_General_100_BIN2 NOT NULL, SkuId NVARCHAR(100) COLLATE Latin1_General_100_BIN2 NOT NULL,
    OnHandUnits BIGINT NOT NULL DEFAULT 0 CHECK(OnHandUnits>=0 AND OnHandUnits<=1000000000000),
    ReservedUnits BIGINT NOT NULL DEFAULT 0 CHECK(ReservedUnits>=0),
    FrozenUnits BIGINT NOT NULL DEFAULT 0 CHECK(FrozenUnits>=0),
    SafetyUnits BIGINT NOT NULL DEFAULT 0 CHECK(SafetyUnits>=0 AND SafetyUnits<=1000000000000),
    Version BIGINT NOT NULL DEFAULT 1,
    PRIMARY KEY(TenantId,OwnerId,WarehouseId,SkuId),
    CHECK(ReservedUnits+FrozenUnits<=OnHandUnits),
    FOREIGN KEY(TenantId,OwnerId,WarehouseId) REFERENCES Warehouses(TenantId,OwnerId,Id),
    FOREIGN KEY(TenantId,SkuId) REFERENCES Skus(TenantId,Id));
CREATE TABLE SalesOrders(Id NVARCHAR(100) COLLATE Latin1_General_100_BIN2 PRIMARY KEY, TenantId NVARCHAR(100) COLLATE Latin1_General_100_BIN2 NOT NULL, Platform NVARCHAR(32) COLLATE Latin1_General_100_BIN2 NOT NULL, ShopId NVARCHAR(100) COLLATE Latin1_General_100_BIN2 NOT NULL,
    ExternalOrderId NVARCHAR(150) COLLATE Latin1_General_100_BIN2 NOT NULL, OwnerId NVARCHAR(100) COLLATE Latin1_General_100_BIN2 NOT NULL, WarehouseId NVARCHAR(100) COLLATE Latin1_General_100_BIN2 NOT NULL,
    State NVARCHAR(64) COLLATE Latin1_General_100_BIN2 NOT NULL CHECK(State IN('PendingReview','Approved','Exception','OnHold','Cancelled')),
    Version BIGINT NOT NULL CHECK(Version>0), SourceHash NVARCHAR(64) COLLATE Latin1_General_100_BIN2 NOT NULL, SourceJson NVARCHAR(MAX) COLLATE Latin1_General_100_BIN2 NOT NULL,
    NormalizedJson NVARCHAR(MAX) COLLATE Latin1_General_100_BIN2, IssuesJson NVARCHAR(MAX) COLLATE Latin1_General_100_BIN2 NOT NULL, PaidCents BIGINT NOT NULL, LineCount BIGINT NOT NULL,
    CreatedAt NVARCHAR(40) COLLATE Latin1_General_100_BIN2 NOT NULL, UpdatedAt NVARCHAR(40) COLLATE Latin1_General_100_BIN2 NOT NULL,
    UNIQUE(TenantId,Platform,ShopId,ExternalOrderId),
    FOREIGN KEY(TenantId,Platform,ShopId) REFERENCES Shops(TenantId,Platform,Id),
    FOREIGN KEY(TenantId,OwnerId,WarehouseId) REFERENCES Warehouses(TenantId,OwnerId,Id));
CREATE INDEX IX_Orders_TenantStateDate ON SalesOrders(TenantId,State,CreatedAt DESC,Id);
CREATE TABLE OrderLines(OrderId NVARCHAR(100) COLLATE Latin1_General_100_BIN2 NOT NULL REFERENCES SalesOrders(Id), ExternalLineId NVARCHAR(100) COLLATE Latin1_General_100_BIN2 NOT NULL,
    SkuId NVARCHAR(100) COLLATE Latin1_General_100_BIN2 NOT NULL, QuantityUnits BIGINT NOT NULL CHECK(QuantityUnits>0), MappingVersion BIGINT NOT NULL,
    SnapshotJson NVARCHAR(MAX) COLLATE Latin1_General_100_BIN2 NOT NULL, PRIMARY KEY(OrderId,ExternalLineId));
CREATE TABLE Reservations(TenantId NVARCHAR(100) COLLATE Latin1_General_100_BIN2 NOT NULL, OrderId NVARCHAR(100) COLLATE Latin1_General_100_BIN2 NOT NULL REFERENCES SalesOrders(Id),
    OwnerId NVARCHAR(100) COLLATE Latin1_General_100_BIN2 NOT NULL, WarehouseId NVARCHAR(100) COLLATE Latin1_General_100_BIN2 NOT NULL, SkuId NVARCHAR(100) COLLATE Latin1_General_100_BIN2 NOT NULL, QuantityUnits BIGINT NOT NULL CHECK(QuantityUnits>0),
    State NVARCHAR(64) COLLATE Latin1_General_100_BIN2 NOT NULL CHECK(State IN('Active','Released')), PRIMARY KEY(TenantId,OrderId,SkuId),
    FOREIGN KEY(TenantId,OwnerId,WarehouseId,SkuId) REFERENCES InventoryBalances(TenantId,OwnerId,WarehouseId,SkuId));
CREATE TABLE InventoryLedger(Id BIGINT IDENTITY(1,1) PRIMARY KEY, TenantId NVARCHAR(100) COLLATE Latin1_General_100_BIN2 NOT NULL, OwnerId NVARCHAR(100) COLLATE Latin1_General_100_BIN2 NOT NULL,
    WarehouseId NVARCHAR(100) COLLATE Latin1_General_100_BIN2 NOT NULL, SkuId NVARCHAR(100) COLLATE Latin1_General_100_BIN2 NOT NULL, OrderId NVARCHAR(100) COLLATE Latin1_General_100_BIN2 REFERENCES SalesOrders(Id), OperationId NVARCHAR(100) COLLATE Latin1_General_100_BIN2 NOT NULL,
    Action NVARCHAR(64) COLLATE Latin1_General_100_BIN2 NOT NULL, OnHandDelta BIGINT NOT NULL, ReservedDelta BIGINT NOT NULL,
    OnHandAfter BIGINT NOT NULL, ReservedAfter BIGINT NOT NULL, FrozenAfter BIGINT NOT NULL, SafetyAfter BIGINT NOT NULL,
    Reason NVARCHAR(MAX) COLLATE Latin1_General_100_BIN2 NOT NULL, CreatedAt NVARCHAR(40) COLLATE Latin1_General_100_BIN2 NOT NULL,
    UNIQUE(TenantId,OperationId,Action,OwnerId,WarehouseId,SkuId),
    FOREIGN KEY(TenantId,OwnerId,WarehouseId,SkuId) REFERENCES InventoryBalances(TenantId,OwnerId,WarehouseId,SkuId));
CREATE INDEX IX_Ledger_Sku ON InventoryLedger(TenantId,SkuId,Id DESC);
CREATE TABLE OrderHistory(Id BIGINT IDENTITY(1,1) PRIMARY KEY, OrderId NVARCHAR(100) COLLATE Latin1_General_100_BIN2 NOT NULL REFERENCES SalesOrders(Id),
    Action NVARCHAR(64) COLLATE Latin1_General_100_BIN2 NOT NULL, FromState NVARCHAR(64) COLLATE Latin1_General_100_BIN2 NOT NULL, ToState NVARCHAR(64) COLLATE Latin1_General_100_BIN2 NOT NULL, Reason NVARCHAR(MAX) COLLATE Latin1_General_100_BIN2 NOT NULL,
    RuleVersion NVARCHAR(100) COLLATE Latin1_General_100_BIN2 NOT NULL, CreatedAt NVARCHAR(40) COLLATE Latin1_General_100_BIN2 NOT NULL);
CREATE TABLE Operations(TenantId NVARCHAR(100) COLLATE Latin1_General_100_BIN2 NOT NULL REFERENCES Tenants(Id), OperationId NVARCHAR(100) COLLATE Latin1_General_100_BIN2 NOT NULL,
    Kind NVARCHAR(64) COLLATE Latin1_General_100_BIN2 NOT NULL, RequestHash NVARCHAR(64) COLLATE Latin1_General_100_BIN2 NOT NULL, ResponseJson NVARCHAR(MAX) COLLATE Latin1_General_100_BIN2 NOT NULL, CreatedAt NVARCHAR(40) COLLATE Latin1_General_100_BIN2 NOT NULL,
    PRIMARY KEY(TenantId,OperationId));
CREATE TABLE OrderSnapshots(OrderId NVARCHAR(100) COLLATE Latin1_General_100_BIN2 NOT NULL REFERENCES SalesOrders(Id), Version BIGINT NOT NULL,
    State NVARCHAR(64) COLLATE Latin1_General_100_BIN2 NOT NULL, SourceJson NVARCHAR(MAX) COLLATE Latin1_General_100_BIN2 NOT NULL, NormalizedJson NVARCHAR(MAX) COLLATE Latin1_General_100_BIN2, IssuesJson NVARCHAR(MAX) COLLATE Latin1_General_100_BIN2 NOT NULL, CreatedAt NVARCHAR(40) COLLATE Latin1_General_100_BIN2 NOT NULL,
    PRIMARY KEY(OrderId,Version));
CREATE TABLE Outbox(Id NVARCHAR(100) COLLATE Latin1_General_100_BIN2 PRIMARY KEY, TenantId NVARCHAR(100) COLLATE Latin1_General_100_BIN2 NOT NULL REFERENCES Tenants(Id), AggregateId NVARCHAR(100) COLLATE Latin1_General_100_BIN2 NOT NULL,
    AggregateVersion BIGINT NOT NULL, EventType NVARCHAR(100) COLLATE Latin1_General_100_BIN2 NOT NULL, PayloadJson NVARCHAR(MAX) COLLATE Latin1_General_100_BIN2 NOT NULL,
    State NVARCHAR(64) COLLATE Latin1_General_100_BIN2 NOT NULL DEFAULT 'Pending', CreatedAt NVARCHAR(40) COLLATE Latin1_General_100_BIN2 NOT NULL,
    UNIQUE(TenantId,AggregateId,AggregateVersion,EventType));

ALTER TABLE Reservations ADD ConsumedUnits BIGINT NOT NULL DEFAULT 0;
ALTER TABLE Reservations ADD CONSTRAINT CK_Reservation_Consumed CHECK(ConsumedUnits>=0 AND ConsumedUnits<=QuantityUnits);
CREATE TABLE ShippingProfiles(OrderId NVARCHAR(100) COLLATE Latin1_General_100_BIN2 PRIMARY KEY REFERENCES SalesOrders(Id), AddressJson NVARCHAR(MAX) COLLATE Latin1_General_100_BIN2 NOT NULL, AddressHash NVARCHAR(64) COLLATE Latin1_General_100_BIN2 NOT NULL,
    AllowMerge BIGINT NOT NULL CHECK(AllowMerge IN(0,1)));
CREATE TABLE Shipments(Id NVARCHAR(100) COLLATE Latin1_General_100_BIN2 PRIMARY KEY, Number NVARCHAR(150) COLLATE Latin1_General_100_BIN2 NOT NULL UNIQUE, TenantId NVARCHAR(100) COLLATE Latin1_General_100_BIN2 NOT NULL, OwnerId NVARCHAR(100) COLLATE Latin1_General_100_BIN2 NOT NULL, WarehouseId NVARCHAR(100) COLLATE Latin1_General_100_BIN2 NOT NULL,
    Platform NVARCHAR(32) COLLATE Latin1_General_100_BIN2 NOT NULL, ShopId NVARCHAR(100) COLLATE Latin1_General_100_BIN2 NOT NULL, AddressJson NVARCHAR(MAX) COLLATE Latin1_General_100_BIN2 NOT NULL, AddressHash NVARCHAR(64) COLLATE Latin1_General_100_BIN2 NOT NULL,
    State NVARCHAR(64) COLLATE Latin1_General_100_BIN2 NOT NULL CHECK(State IN('Draft','Picking','Packed','Shipped','Voided','Superseded')), Version BIGINT NOT NULL DEFAULT 1,
    Carrier NVARCHAR(100) COLLATE Latin1_General_100_BIN2 NOT NULL DEFAULT '', TrackingNumber NVARCHAR(100) COLLATE Latin1_General_100_BIN2 NOT NULL DEFAULT '', CreatedAt NVARCHAR(40) COLLATE Latin1_General_100_BIN2 NOT NULL, UpdatedAt NVARCHAR(40) COLLATE Latin1_General_100_BIN2 NOT NULL,
    FOREIGN KEY(TenantId,OwnerId,WarehouseId) REFERENCES Warehouses(TenantId,OwnerId,Id));
CREATE INDEX IX_Shipments_StateDate ON Shipments(TenantId,State,CreatedAt DESC);
CREATE UNIQUE INDEX UX_Shipment_Tracking ON Shipments(TenantId,Carrier,TrackingNumber) WHERE TrackingNumber<>'' AND State<>'Voided' AND State<>'Superseded';
CREATE TABLE ShipmentLines(Id NVARCHAR(100) COLLATE Latin1_General_100_BIN2 PRIMARY KEY, ShipmentId NVARCHAR(100) COLLATE Latin1_General_100_BIN2 NOT NULL REFERENCES Shipments(Id), OrderId NVARCHAR(100) COLLATE Latin1_General_100_BIN2 NOT NULL REFERENCES SalesOrders(Id),
    ExternalLineId NVARCHAR(100) COLLATE Latin1_General_100_BIN2 NOT NULL, QuantityUnits BIGINT NOT NULL CHECK(QuantityUnits>0), SnapshotJson NVARCHAR(MAX) COLLATE Latin1_General_100_BIN2 NOT NULL,
    UNIQUE(ShipmentId,OrderId,ExternalLineId));
CREATE INDEX IX_ShipmentLines_OrderLine ON ShipmentLines(OrderId,ExternalLineId);
CREATE TABLE ShipmentComponents(ShipmentLineId NVARCHAR(100) COLLATE Latin1_General_100_BIN2 NOT NULL REFERENCES ShipmentLines(Id), SkuId NVARCHAR(100) COLLATE Latin1_General_100_BIN2 NOT NULL, QuantityUnits BIGINT NOT NULL CHECK(QuantityUnits>0),
    PRIMARY KEY(ShipmentLineId,SkuId));
CREATE TABLE ShipmentChecks(ShipmentId NVARCHAR(100) COLLATE Latin1_General_100_BIN2 NOT NULL REFERENCES Shipments(Id), SkuId NVARCHAR(100) COLLATE Latin1_General_100_BIN2 NOT NULL, RequiredUnits BIGINT NOT NULL CHECK(RequiredUnits>0),
    VerifiedUnits BIGINT NOT NULL DEFAULT 0, PRIMARY KEY(ShipmentId,SkuId), CHECK(VerifiedUnits>=0 AND VerifiedUnits<=RequiredUnits));
CREATE TABLE ShipmentHistory(Id BIGINT IDENTITY(1,1) PRIMARY KEY, ShipmentId NVARCHAR(100) COLLATE Latin1_General_100_BIN2 NOT NULL REFERENCES Shipments(Id), Action NVARCHAR(64) COLLATE Latin1_General_100_BIN2 NOT NULL,
    Actor NVARCHAR(MAX) COLLATE Latin1_General_100_BIN2 NOT NULL, Reason NVARCHAR(MAX) COLLATE Latin1_General_100_BIN2 NOT NULL, DataJson NVARCHAR(MAX) COLLATE Latin1_General_100_BIN2 NOT NULL, CreatedAt NVARCHAR(40) COLLATE Latin1_General_100_BIN2 NOT NULL);
CREATE TABLE ShipmentRelations(SourceId NVARCHAR(100) COLLATE Latin1_General_100_BIN2 NOT NULL REFERENCES Shipments(Id), TargetId NVARCHAR(100) COLLATE Latin1_General_100_BIN2 NOT NULL REFERENCES Shipments(Id), Kind NVARCHAR(64) COLLATE Latin1_General_100_BIN2 NOT NULL,
    PRIMARY KEY(SourceId,TargetId));
CREATE TABLE ShipmentMovements(ShipmentId NVARCHAR(100) COLLATE Latin1_General_100_BIN2 NOT NULL REFERENCES Shipments(Id), OrderId NVARCHAR(100) COLLATE Latin1_General_100_BIN2 NOT NULL REFERENCES SalesOrders(Id),
    SkuId NVARCHAR(100) COLLATE Latin1_General_100_BIN2 NOT NULL, QuantityUnits BIGINT NOT NULL CHECK(QuantityUnits>0), PRIMARY KEY(ShipmentId,OrderId,SkuId));
ALTER TABLE InventoryLedger ADD ShipmentId NVARCHAR(100) COLLATE Latin1_General_100_BIN2 REFERENCES Shipments(Id);
CREATE TABLE SkuBarcodes(TenantId NVARCHAR(100) COLLATE Latin1_General_100_BIN2 NOT NULL, Barcode NVARCHAR(100) COLLATE Latin1_General_100_BIN2 NOT NULL, SkuId NVARCHAR(100) COLLATE Latin1_General_100_BIN2 NOT NULL, Version BIGINT NOT NULL DEFAULT 1,
    PRIMARY KEY(TenantId,Barcode), FOREIGN KEY(TenantId,SkuId) REFERENCES Skus(TenantId,Id));

CREATE TABLE WarehouseConfigurationHistory(Id BIGINT IDENTITY(1,1) PRIMARY KEY, Entity NVARCHAR(MAX) COLLATE Latin1_General_100_BIN2 NOT NULL, EntityId NVARCHAR(100) COLLATE Latin1_General_100_BIN2 NOT NULL, Actor NVARCHAR(MAX) COLLATE Latin1_General_100_BIN2 NOT NULL,
    Reason NVARCHAR(MAX) COLLATE Latin1_General_100_BIN2 NOT NULL, DataJson NVARCHAR(MAX) COLLATE Latin1_General_100_BIN2 NOT NULL, CreatedAt NVARCHAR(40) COLLATE Latin1_General_100_BIN2 NOT NULL);
CREATE TABLE DeliveryJobs(Id NVARCHAR(100) COLLATE Latin1_General_100_BIN2 PRIMARY KEY, ShipmentId NVARCHAR(100) COLLATE Latin1_General_100_BIN2 NOT NULL REFERENCES Shipments(Id), OrderId NVARCHAR(100) COLLATE Latin1_General_100_BIN2 NOT NULL REFERENCES SalesOrders(Id),
    PayloadJson NVARCHAR(MAX) COLLATE Latin1_General_100_BIN2 NOT NULL, State NVARCHAR(64) COLLATE Latin1_General_100_BIN2 NOT NULL CHECK(State IN('Blocked','Pending','Processing','Unknown','Rejected','Confirmed')),
    Version BIGINT NOT NULL DEFAULT 1, Attempts BIGINT NOT NULL DEFAULT 0, NextAttemptAt NVARCHAR(40) COLLATE Latin1_General_100_BIN2, LeaseToken NVARCHAR(100) COLLATE Latin1_General_100_BIN2, LeaseUntil NVARCHAR(40) COLLATE Latin1_General_100_BIN2,
    LastError NVARCHAR(MAX) COLLATE Latin1_General_100_BIN2 NOT NULL DEFAULT '', Receipt NVARCHAR(MAX) COLLATE Latin1_General_100_BIN2 NOT NULL DEFAULT '', CreatedAt NVARCHAR(40) COLLATE Latin1_General_100_BIN2 NOT NULL, UpdatedAt NVARCHAR(40) COLLATE Latin1_General_100_BIN2 NOT NULL,
    UNIQUE(ShipmentId,OrderId));
CREATE INDEX IX_DeliveryJobs_Queue ON DeliveryJobs(State,NextAttemptAt);
CREATE TABLE DeliveryAttempts(Id BIGINT IDENTITY(1,1) PRIMARY KEY, JobId NVARCHAR(100) COLLATE Latin1_General_100_BIN2 NOT NULL REFERENCES DeliveryJobs(Id), LeaseToken NVARCHAR(100) COLLATE Latin1_General_100_BIN2 NOT NULL,
    Outcome NVARCHAR(64) COLLATE Latin1_General_100_BIN2 NOT NULL, Message NVARCHAR(MAX) COLLATE Latin1_General_100_BIN2 NOT NULL, Receipt NVARCHAR(MAX) COLLATE Latin1_General_100_BIN2 NOT NULL DEFAULT '', CreatedAt NVARCHAR(40) COLLATE Latin1_General_100_BIN2 NOT NULL);

CREATE TABLE AfterSaleCases(Id NVARCHAR(100) COLLATE Latin1_General_100_BIN2 PRIMARY KEY, Number NVARCHAR(150) COLLATE Latin1_General_100_BIN2 NOT NULL UNIQUE, TenantId NVARCHAR(100) COLLATE Latin1_General_100_BIN2 NOT NULL, OrderId NVARCHAR(100) COLLATE Latin1_General_100_BIN2 NOT NULL REFERENCES SalesOrders(Id),
    Platform NVARCHAR(32) COLLATE Latin1_General_100_BIN2 NOT NULL, ShopId NVARCHAR(100) COLLATE Latin1_General_100_BIN2 NOT NULL, SourceCaseNumber NVARCHAR(100) COLLATE Latin1_General_100_BIN2 NOT NULL, RequestHash NVARCHAR(64) COLLATE Latin1_General_100_BIN2 NOT NULL,
    Kind NVARCHAR(64) COLLATE Latin1_General_100_BIN2 NOT NULL CHECK(Kind IN('CancelUnshipped','RefundOnly','ReturnRefund')),
    State NVARCHAR(64) COLLATE Latin1_General_100_BIN2 NOT NULL CHECK(State IN('Open','Approved','Closed','Rejected','Withdrawn')), Version BIGINT NOT NULL DEFAULT 1,
    RefundCents BIGINT NOT NULL CHECK(RefundCents>0), RefundState NVARCHAR(64) COLLATE Latin1_General_100_BIN2 NOT NULL DEFAULT 'Pending' CHECK(RefundState IN('Pending','Unknown','Failed','EvidenceRecorded')),
    RefundReference NVARCHAR(100) COLLATE Latin1_General_100_BIN2 NOT NULL DEFAULT '', ShortReturnAccepted BIGINT NOT NULL DEFAULT 0 CHECK(ShortReturnAccepted IN(0,1)),
    CreatedAt NVARCHAR(40) COLLATE Latin1_General_100_BIN2 NOT NULL, UpdatedAt NVARCHAR(40) COLLATE Latin1_General_100_BIN2 NOT NULL, UNIQUE(TenantId,Platform,ShopId,SourceCaseNumber));
CREATE INDEX IX_AfterSale_OrderState ON AfterSaleCases(OrderId,State);
CREATE INDEX IX_AfterSale_StateDate ON AfterSaleCases(TenantId,State,CreatedAt DESC);
CREATE TABLE AfterSaleLines(Id NVARCHAR(100) COLLATE Latin1_General_100_BIN2 PRIMARY KEY, CaseId NVARCHAR(100) COLLATE Latin1_General_100_BIN2 NOT NULL REFERENCES AfterSaleCases(Id), ShipmentLineId NVARCHAR(100) COLLATE Latin1_General_100_BIN2 REFERENCES ShipmentLines(Id),
    ExternalLineId NVARCHAR(100) COLLATE Latin1_General_100_BIN2 NOT NULL, QuantityUnits BIGINT NOT NULL CHECK(QuantityUnits>0), SnapshotJson NVARCHAR(MAX) COLLATE Latin1_General_100_BIN2 NOT NULL);
CREATE TABLE ReturnComponents(CaseLineId NVARCHAR(100) COLLATE Latin1_General_100_BIN2 NOT NULL REFERENCES AfterSaleLines(Id), SkuId NVARCHAR(100) COLLATE Latin1_General_100_BIN2 NOT NULL, ExpectedUnits BIGINT NOT NULL CHECK(ExpectedUnits>0),
    GoodUnits BIGINT NOT NULL DEFAULT 0 CHECK(GoodUnits>=0), DamagedUnits BIGINT NOT NULL DEFAULT 0 CHECK(DamagedUnits>=0),
    PRIMARY KEY(CaseLineId,SkuId), CHECK(GoodUnits+DamagedUnits<=ExpectedUnits));
CREATE TABLE ReturnReceipts(Id NVARCHAR(100) COLLATE Latin1_General_100_BIN2 PRIMARY KEY, TenantId NVARCHAR(100) COLLATE Latin1_General_100_BIN2 NOT NULL, CaseId NVARCHAR(100) COLLATE Latin1_General_100_BIN2 NOT NULL REFERENCES AfterSaleCases(Id),
    ReceiptNumber NVARCHAR(100) COLLATE Latin1_General_100_BIN2 NOT NULL, ReturnTracking NVARCHAR(100) COLLATE Latin1_General_100_BIN2 NOT NULL, RequestHash NVARCHAR(64) COLLATE Latin1_General_100_BIN2 NOT NULL, Actor NVARCHAR(MAX) COLLATE Latin1_General_100_BIN2 NOT NULL, Reason NVARCHAR(MAX) COLLATE Latin1_General_100_BIN2 NOT NULL, CreatedAt NVARCHAR(40) COLLATE Latin1_General_100_BIN2 NOT NULL,
    UNIQUE(TenantId,ReceiptNumber));
CREATE TABLE ReturnReceiptLines(ReceiptId NVARCHAR(100) COLLATE Latin1_General_100_BIN2 NOT NULL REFERENCES ReturnReceipts(Id), CaseLineId NVARCHAR(100) COLLATE Latin1_General_100_BIN2 NOT NULL, SkuId NVARCHAR(100) COLLATE Latin1_General_100_BIN2 NOT NULL,
    GoodUnits BIGINT NOT NULL CHECK(GoodUnits>=0), DamagedUnits BIGINT NOT NULL CHECK(DamagedUnits>=0), CHECK(GoodUnits+DamagedUnits>0),
    PRIMARY KEY(ReceiptId,CaseLineId,SkuId), FOREIGN KEY(CaseLineId,SkuId) REFERENCES ReturnComponents(CaseLineId,SkuId));
ALTER TABLE InventoryLedger ADD AfterSaleId NVARCHAR(100) COLLATE Latin1_General_100_BIN2 REFERENCES AfterSaleCases(Id);
ALTER TABLE InventoryLedger ADD ReturnReceiptId NVARCHAR(100) COLLATE Latin1_General_100_BIN2 REFERENCES ReturnReceipts(Id);
CREATE TABLE QuarantineBalances(TenantId NVARCHAR(100) COLLATE Latin1_General_100_BIN2 NOT NULL, OwnerId NVARCHAR(100) COLLATE Latin1_General_100_BIN2 NOT NULL, WarehouseId NVARCHAR(100) COLLATE Latin1_General_100_BIN2 NOT NULL, SkuId NVARCHAR(100) COLLATE Latin1_General_100_BIN2 NOT NULL,
    QuantityUnits BIGINT NOT NULL DEFAULT 0 CHECK(QuantityUnits>=0 AND QuantityUnits<=1000000000000), Version BIGINT NOT NULL DEFAULT 1,
    PRIMARY KEY(TenantId,OwnerId,WarehouseId,SkuId), FOREIGN KEY(TenantId,SkuId) REFERENCES Skus(TenantId,Id));

CREATE TABLE QuarantineLedger(Id BIGINT IDENTITY(1,1) PRIMARY KEY, TenantId NVARCHAR(100) COLLATE Latin1_General_100_BIN2 NOT NULL, OwnerId NVARCHAR(100) COLLATE Latin1_General_100_BIN2 NOT NULL, WarehouseId NVARCHAR(100) COLLATE Latin1_General_100_BIN2 NOT NULL, SkuId NVARCHAR(100) COLLATE Latin1_General_100_BIN2 NOT NULL,
    CaseId NVARCHAR(100) COLLATE Latin1_General_100_BIN2 NOT NULL REFERENCES AfterSaleCases(Id), ReceiptId NVARCHAR(100) COLLATE Latin1_General_100_BIN2 NOT NULL REFERENCES ReturnReceipts(Id), OperationId NVARCHAR(100) COLLATE Latin1_General_100_BIN2 NOT NULL,
    QuantityUnits BIGINT NOT NULL CHECK(QuantityUnits>0), BalanceAfter BIGINT NOT NULL, Actor NVARCHAR(MAX) COLLATE Latin1_General_100_BIN2 NOT NULL, Reason NVARCHAR(MAX) COLLATE Latin1_General_100_BIN2 NOT NULL, CreatedAt NVARCHAR(40) COLLATE Latin1_General_100_BIN2 NOT NULL,
    UNIQUE(TenantId,ReceiptId,SkuId));
CREATE TABLE RefundObservations(Id BIGINT IDENTITY(1,1) PRIMARY KEY, TenantId NVARCHAR(100) COLLATE Latin1_General_100_BIN2 NOT NULL, CaseId NVARCHAR(100) COLLATE Latin1_General_100_BIN2 NOT NULL REFERENCES AfterSaleCases(Id), EventKey NVARCHAR(100) COLLATE Latin1_General_100_BIN2 NOT NULL,
    RequestHash NVARCHAR(64) COLLATE Latin1_General_100_BIN2 NOT NULL, Status NVARCHAR(MAX) COLLATE Latin1_General_100_BIN2 NOT NULL CHECK(Status IN('Unknown','Failed','EvidenceRecorded')), AmountCents BIGINT NOT NULL CHECK(AmountCents>0),
    RefundReference NVARCHAR(100) COLLATE Latin1_General_100_BIN2 NOT NULL, Evidence NVARCHAR(MAX) COLLATE Latin1_General_100_BIN2 NOT NULL, ObservedAt NVARCHAR(40) COLLATE Latin1_General_100_BIN2 NOT NULL, Actor NVARCHAR(MAX) COLLATE Latin1_General_100_BIN2 NOT NULL, Reason NVARCHAR(MAX) COLLATE Latin1_General_100_BIN2 NOT NULL, CreatedAt NVARCHAR(40) COLLATE Latin1_General_100_BIN2 NOT NULL,
    UNIQUE(TenantId,EventKey));
CREATE TABLE RefundEvidence(CaseId NVARCHAR(100) COLLATE Latin1_General_100_BIN2 PRIMARY KEY REFERENCES AfterSaleCases(Id), TenantId NVARCHAR(100) COLLATE Latin1_General_100_BIN2 NOT NULL, Platform NVARCHAR(32) COLLATE Latin1_General_100_BIN2 NOT NULL, ShopId NVARCHAR(100) COLLATE Latin1_General_100_BIN2 NOT NULL,
    RefundReference NVARCHAR(100) COLLATE Latin1_General_100_BIN2 NOT NULL, AmountCents BIGINT NOT NULL CHECK(AmountCents>0), ObservationId BIGINT NOT NULL REFERENCES RefundObservations(Id),
    UNIQUE(TenantId,Platform,ShopId,RefundReference));
CREATE TABLE AfterSaleHistory(Id BIGINT IDENTITY(1,1) PRIMARY KEY, CaseId NVARCHAR(100) COLLATE Latin1_General_100_BIN2 NOT NULL REFERENCES AfterSaleCases(Id), Action NVARCHAR(64) COLLATE Latin1_General_100_BIN2 NOT NULL,
    Actor NVARCHAR(MAX) COLLATE Latin1_General_100_BIN2 NOT NULL, Reason NVARCHAR(MAX) COLLATE Latin1_General_100_BIN2 NOT NULL, DataJson NVARCHAR(MAX) COLLATE Latin1_General_100_BIN2 NOT NULL, CreatedAt NVARCHAR(40) COLLATE Latin1_General_100_BIN2 NOT NULL);

CREATE TABLE BillBatches(Id NVARCHAR(100) COLLATE Latin1_General_100_BIN2 PRIMARY KEY, TenantId NVARCHAR(100) COLLATE Latin1_General_100_BIN2 NOT NULL, Platform NVARCHAR(32) COLLATE Latin1_General_100_BIN2 NOT NULL, ShopId NVARCHAR(100) COLLATE Latin1_General_100_BIN2 NOT NULL,
 Number NVARCHAR(150) COLLATE Latin1_General_100_BIN2 NOT NULL, FileName NVARCHAR(MAX) COLLATE Latin1_General_100_BIN2 NOT NULL, ContentHash NVARCHAR(64) COLLATE Latin1_General_100_BIN2 NOT NULL, RequestHash NVARCHAR(64) COLLATE Latin1_General_100_BIN2 NOT NULL, RawContent NVARCHAR(MAX) COLLATE Latin1_General_100_BIN2 NOT NULL, MappingJson NVARCHAR(MAX) COLLATE Latin1_General_100_BIN2 NOT NULL,
 NewRows BIGINT NOT NULL, DuplicateRows BIGINT NOT NULL, State NVARCHAR(64) COLLATE Latin1_General_100_BIN2 NOT NULL CHECK(State IN('Active','Voided')), Version BIGINT NOT NULL DEFAULT 1, CreatedAt NVARCHAR(40) COLLATE Latin1_General_100_BIN2 NOT NULL,
 UNIQUE(TenantId,Platform,ShopId,Number));
CREATE TABLE BillRows(Id NVARCHAR(100) COLLATE Latin1_General_100_BIN2 PRIMARY KEY, BatchId NVARCHAR(100) COLLATE Latin1_General_100_BIN2 NOT NULL REFERENCES BillBatches(Id), TenantId NVARCHAR(100) COLLATE Latin1_General_100_BIN2 NOT NULL, Platform NVARCHAR(32) COLLATE Latin1_General_100_BIN2 NOT NULL, ShopId NVARCHAR(100) COLLATE Latin1_General_100_BIN2 NOT NULL,
 TransactionId NVARCHAR(150) COLLATE Latin1_General_100_BIN2 NOT NULL, ExternalOrderId NVARCHAR(150) COLLATE Latin1_General_100_BIN2 NOT NULL, Kind NVARCHAR(64) COLLATE Latin1_General_100_BIN2 NOT NULL CHECK(Kind IN('Sale','Refund','PlatformFee','Freight')), AmountCents BIGINT NOT NULL CHECK(AmountCents>0),
 OccurredAt NVARCHAR(40) COLLATE Latin1_General_100_BIN2 NOT NULL, SourceCase NVARCHAR(150) COLLATE Latin1_General_100_BIN2 NOT NULL, SourceHash NVARCHAR(64) COLLATE Latin1_General_100_BIN2 NOT NULL, RawJson NVARCHAR(MAX) COLLATE Latin1_General_100_BIN2 NOT NULL,
 OrderId NVARCHAR(100) COLLATE Latin1_General_100_BIN2 REFERENCES SalesOrders(Id), CaseId NVARCHAR(100) COLLATE Latin1_General_100_BIN2 REFERENCES AfterSaleCases(Id), Version BIGINT NOT NULL DEFAULT 1,
 UNIQUE(TenantId,Platform,ShopId,TransactionId));
CREATE INDEX IX_BillRows_Order ON BillRows(OrderId);
CREATE TABLE SkuCosts(SkuId NVARCHAR(100) COLLATE Latin1_General_100_BIN2 PRIMARY KEY, UnitCostMicros BIGINT NOT NULL CHECK(UnitCostMicros>=0 AND UnitCostMicros<=1000000000000), Version BIGINT NOT NULL, Evidence NVARCHAR(MAX) COLLATE Latin1_General_100_BIN2 NOT NULL);
CREATE TABLE ShipmentCosts(ShipmentLineId NVARCHAR(100) COLLATE Latin1_General_100_BIN2 NOT NULL REFERENCES ShipmentLines(Id), SkuId NVARCHAR(100) COLLATE Latin1_General_100_BIN2 NOT NULL, QuantityUnits BIGINT NOT NULL CHECK(QuantityUnits>0),
 UnitCostMicros BIGINT, CostCents BIGINT, Version BIGINT NOT NULL DEFAULT 1, Source NVARCHAR(MAX) COLLATE Latin1_General_100_BIN2 NOT NULL,
 PRIMARY KEY(ShipmentLineId,SkuId), CHECK((UnitCostMicros IS NULL AND CostCents IS NULL) OR (UnitCostMicros>=0 AND CostCents>=0)));

CREATE TABLE OrderFeePlans(OrderId NVARCHAR(100) COLLATE Latin1_General_100_BIN2 PRIMARY KEY REFERENCES SalesOrders(Id), PlatformFeeCents BIGINT NOT NULL CHECK(PlatformFeeCents>=0), FreightCents BIGINT NOT NULL CHECK(FreightCents>=0), Version BIGINT NOT NULL, Evidence NVARCHAR(MAX) COLLATE Latin1_General_100_BIN2 NOT NULL);
CREATE TABLE FinanceHistory(Id BIGINT IDENTITY(1,1) PRIMARY KEY, EntityId NVARCHAR(100) COLLATE Latin1_General_100_BIN2 NOT NULL, Action NVARCHAR(64) COLLATE Latin1_General_100_BIN2 NOT NULL, Actor NVARCHAR(MAX) COLLATE Latin1_General_100_BIN2 NOT NULL, Reason NVARCHAR(MAX) COLLATE Latin1_General_100_BIN2 NOT NULL, DataJson NVARCHAR(MAX) COLLATE Latin1_General_100_BIN2 NOT NULL, CreatedAt NVARCHAR(40) COLLATE Latin1_General_100_BIN2 NOT NULL);
CREATE TABLE FinanceExports(Id NVARCHAR(100) COLLATE Latin1_General_100_BIN2 PRIMARY KEY, Number NVARCHAR(150) COLLATE Latin1_General_100_BIN2 NOT NULL UNIQUE, Target NVARCHAR(MAX) COLLATE Latin1_General_100_BIN2 NOT NULL, RequestHash NVARCHAR(64) COLLATE Latin1_General_100_BIN2 NOT NULL, ContentHash NVARCHAR(64) COLLATE Latin1_General_100_BIN2 NOT NULL,
 JsonContent NVARCHAR(MAX) COLLATE Latin1_General_100_BIN2 NOT NULL, CsvContent NVARCHAR(MAX) COLLATE Latin1_General_100_BIN2 NOT NULL, CsvHash NVARCHAR(64) COLLATE Latin1_General_100_BIN2 NOT NULL, State NVARCHAR(64) COLLATE Latin1_General_100_BIN2 NOT NULL CHECK(State IN('Prepared','Exported')), Version BIGINT NOT NULL DEFAULT 1, CreatedAt NVARCHAR(40) COLLATE Latin1_General_100_BIN2 NOT NULL);
CREATE TABLE FinanceExportOrders(ExportId NVARCHAR(100) COLLATE Latin1_General_100_BIN2 NOT NULL REFERENCES FinanceExports(Id), OrderId NVARCHAR(100) COLLATE Latin1_General_100_BIN2 NOT NULL REFERENCES SalesOrders(Id), Fingerprint NVARCHAR(64) COLLATE Latin1_General_100_BIN2 NOT NULL, PRIMARY KEY(ExportId,OrderId));
CREATE TABLE FinanceExportRows(ExportId NVARCHAR(100) COLLATE Latin1_General_100_BIN2 NOT NULL REFERENCES FinanceExports(Id), RowId NVARCHAR(100) COLLATE Latin1_General_100_BIN2 NOT NULL REFERENCES BillRows(Id), PRIMARY KEY(ExportId,RowId));

CREATE UNIQUE INDEX UX_AfterSaleLines_Shipment ON AfterSaleLines(CaseId,ShipmentLineId) WHERE ShipmentLineId IS NOT NULL;
CREATE TABLE SystemMetadata(Name NVARCHAR(100) COLLATE Latin1_General_100_BIN2 PRIMARY KEY, Value NVARCHAR(MAX) COLLATE Latin1_General_100_BIN2 NOT NULL);

CREATE TABLE SecurityUsers(Id NVARCHAR(100) COLLATE Latin1_General_100_BIN2 PRIMARY KEY, Username NVARCHAR(100) COLLATE Latin1_General_100_BIN2 NOT NULL UNIQUE, DisplayName NVARCHAR(100) COLLATE Latin1_General_100_BIN2 NOT NULL,
 Role NVARCHAR(100) COLLATE Latin1_General_100_BIN2 NOT NULL, TenantId NVARCHAR(100) COLLATE Latin1_General_100_BIN2 NOT NULL REFERENCES Tenants(Id), Enabled BIGINT NOT NULL CHECK(Enabled IN(0,1)),
 Version BIGINT NOT NULL, MustChangePassword BIGINT NOT NULL CHECK(MustChangePassword IN(0,1)), PasswordHash NVARCHAR(MAX) COLLATE Latin1_General_100_BIN2 NOT NULL,
 FailedAttempts BIGINT NOT NULL DEFAULT 0, LockedUntil NVARCHAR(100) COLLATE Latin1_General_100_BIN2, CreatedAt NVARCHAR(100) COLLATE Latin1_General_100_BIN2 NOT NULL);
CREATE TABLE SecurityUserShops(UserId NVARCHAR(100) COLLATE Latin1_General_100_BIN2 NOT NULL REFERENCES SecurityUsers(Id), ShopId NVARCHAR(100) COLLATE Latin1_General_100_BIN2 NOT NULL, PRIMARY KEY(UserId,ShopId));
CREATE TABLE SecurityUserWarehouses(UserId NVARCHAR(100) COLLATE Latin1_General_100_BIN2 NOT NULL REFERENCES SecurityUsers(Id), WarehouseId NVARCHAR(100) COLLATE Latin1_General_100_BIN2 NOT NULL, PRIMARY KEY(UserId,WarehouseId));
CREATE TABLE SecuritySessions(TokenHash NVARCHAR(100) COLLATE Latin1_General_100_BIN2 PRIMARY KEY, UserId NVARCHAR(100) COLLATE Latin1_General_100_BIN2 NOT NULL REFERENCES SecurityUsers(Id), UserVersion BIGINT NOT NULL,
 ExpiresAt NVARCHAR(100) COLLATE Latin1_General_100_BIN2 NOT NULL, Revoked BIGINT NOT NULL DEFAULT 0 CHECK(Revoked IN(0,1)));
CREATE INDEX IX_SecuritySessions_User ON SecuritySessions(UserId);
CREATE TABLE SecurityOperationOwners(OperationId NVARCHAR(100) COLLATE Latin1_General_100_BIN2 PRIMARY KEY, UserId NVARCHAR(100) COLLATE Latin1_General_100_BIN2 NOT NULL REFERENCES SecurityUsers(Id));
CREATE TABLE SecurityAudit(Id BIGINT IDENTITY(1,1) PRIMARY KEY, ActorId NVARCHAR(100) COLLATE Latin1_General_100_BIN2 NOT NULL, ActorName NVARCHAR(100) COLLATE Latin1_General_100_BIN2 NOT NULL, Action NVARCHAR(100) COLLATE Latin1_General_100_BIN2 NOT NULL,
 Resource NVARCHAR(MAX) COLLATE Latin1_General_100_BIN2 NOT NULL, Outcome NVARCHAR(100) COLLATE Latin1_General_100_BIN2 NOT NULL, OperationId NVARCHAR(100) COLLATE Latin1_General_100_BIN2 NOT NULL, CreatedAt NVARCHAR(100) COLLATE Latin1_General_100_BIN2 NOT NULL, Reason NVARCHAR(500) COLLATE Latin1_General_100_BIN2 NOT NULL);

ALTER TABLE Outbox ADD Version BIGINT NOT NULL DEFAULT 1,Attempts BIGINT NOT NULL DEFAULT 0,CycleAttempts BIGINT NOT NULL DEFAULT 0,
    NextAttemptAt NVARCHAR(40) COLLATE Latin1_General_100_BIN2,LeaseToken NVARCHAR(100) COLLATE Latin1_General_100_BIN2,LeaseUntil NVARCHAR(40) COLLATE Latin1_General_100_BIN2,
    LastCode NVARCHAR(100) COLLATE Latin1_General_100_BIN2 NOT NULL DEFAULT '',Receipt NVARCHAR(2000) COLLATE Latin1_General_100_BIN2 NOT NULL DEFAULT '',UpdatedAt NVARCHAR(40) COLLATE Latin1_General_100_BIN2 NOT NULL DEFAULT '';
UPDATE Outbox SET UpdatedAt=CreatedAt,NextAttemptAt=CreatedAt;
CREATE INDEX IX_Outbox_Due ON Outbox(State,NextAttemptAt,CreatedAt);
CREATE TABLE OutboxAttempts(LeaseToken NVARCHAR(100) COLLATE Latin1_General_100_BIN2 PRIMARY KEY,TaskId NVARCHAR(100) COLLATE Latin1_General_100_BIN2 NOT NULL REFERENCES Outbox(Id),Attempt BIGINT NOT NULL,
    Outcome NVARCHAR(100) COLLATE Latin1_General_100_BIN2 NOT NULL,StartedAt NVARCHAR(40) COLLATE Latin1_General_100_BIN2 NOT NULL,FinishedAt NVARCHAR(40) COLLATE Latin1_General_100_BIN2);
CREATE INDEX IX_OutboxAttempts_Task ON OutboxAttempts(TaskId,StartedAt);
CREATE TABLE TaskActions(Id NVARCHAR(100) COLLATE Latin1_General_100_BIN2 PRIMARY KEY,TaskId NVARCHAR(100) COLLATE Latin1_General_100_BIN2 NOT NULL REFERENCES Outbox(Id),Actor NVARCHAR(100) COLLATE Latin1_General_100_BIN2 NOT NULL,Reason NVARCHAR(500) COLLATE Latin1_General_100_BIN2 NOT NULL,CreatedAt NVARCHAR(40) COLLATE Latin1_General_100_BIN2 NOT NULL);
