CREATE TABLE InventoryDocumentHistory(Id NVARCHAR(100) COLLATE Latin1_General_100_BIN2 PRIMARY KEY,DocumentId NVARCHAR(100) COLLATE Latin1_General_100_BIN2 NOT NULL REFERENCES InventoryDocuments(Id),Action NVARCHAR(100) COLLATE Latin1_General_100_BIN2 NOT NULL,ActorId NVARCHAR(100) COLLATE Latin1_General_100_BIN2 NOT NULL,Reason NVARCHAR(MAX) COLLATE Latin1_General_100_BIN2 NOT NULL,CreatedAt NVARCHAR(100) COLLATE Latin1_General_100_BIN2 NOT NULL,DataJson NVARCHAR(MAX) COLLATE Latin1_General_100_BIN2 NOT NULL);
