CREATE TABLE InventoryMovements(DocumentId NVARCHAR(100) COLLATE Latin1_General_100_BIN2 NOT NULL REFERENCES InventoryDocuments(Id),SkuId NVARCHAR(100) COLLATE Latin1_General_100_BIN2 NOT NULL,OnHandDelta BIGINT NOT NULL,QuarantineDelta BIGINT NOT NULL,OnHandAfter BIGINT NOT NULL,QuarantineAfter BIGINT NOT NULL,InventoryVersion BIGINT NOT NULL,QuarantineVersion BIGINT NOT NULL,PRIMARY KEY(DocumentId,SkuId));
CREATE TABLE InventoryReversals(OriginalId NVARCHAR(100) COLLATE Latin1_General_100_BIN2 PRIMARY KEY REFERENCES InventoryDocuments(Id),ReversalId NVARCHAR(100) COLLATE Latin1_General_100_BIN2 NOT NULL UNIQUE REFERENCES InventoryDocuments(Id));
ALTER TABLE InventoryLedger ADD StockDocumentId NVARCHAR(100) COLLATE Latin1_General_100_BIN2 NULL REFERENCES InventoryDocuments(Id);
